CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE tenants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, state text NOT NULL DEFAULT 'trial' CHECK(state IN ('trial','active','suspended','expired')), storage_limit bigint NOT NULL DEFAULT 104857600, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE branches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),name text NOT NULL,currency text NOT NULL DEFAULT 'PKR',timezone text NOT NULL DEFAULT 'Asia/Karachi',cutoff integer NOT NULL DEFAULT 0 CHECK(cutoff BETWEEN 0 AND 23),settings jsonb NOT NULL DEFAULT '{}',UNIQUE(tenant_id,id));
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),email text NOT NULL UNIQUE,name text NOT NULL,staff_id text NOT NULL,password_hash text NOT NULL,role text NOT NULL,permissions jsonb NOT NULL DEFAULT '[]',branches jsonb NOT NULL DEFAULT '[]',station_ids jsonb NOT NULL DEFAULT '[]',active boolean NOT NULL DEFAULT true,token_version integer NOT NULL DEFAULT 0,UNIQUE(tenant_id,id),UNIQUE(tenant_id,staff_id));
CREATE TABLE resources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),branch_id uuid,name text NOT NULL,kind text NOT NULL,data jsonb NOT NULL DEFAULT '{}',active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,branch_id,id),FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id));
CREATE INDEX resources_scope ON resources(tenant_id,branch_id,kind);
CREATE TABLE tables (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,branch_id uuid NOT NULL,name text NOT NULL,capacity integer NOT NULL CHECK(capacity>0),state text NOT NULL DEFAULT 'available' CHECK(state IN ('available','occupied','reserved','cleaning')),hall_id uuid,waiter_id uuid,qr_hash text NOT NULL UNIQUE,UNIQUE(tenant_id,id),UNIQUE(tenant_id,branch_id,id),FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id),FOREIGN KEY(tenant_id,branch_id,hall_id) REFERENCES resources(tenant_id,branch_id,id),FOREIGN KEY(tenant_id,waiter_id) REFERENCES users(tenant_id,id));
CREATE TABLE sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,branch_id uuid NOT NULL,table_id uuid,pin_hash text,state text NOT NULL DEFAULT 'open' CHECK(state IN ('open','closed')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,branch_id,id),FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id),FOREIGN KEY(tenant_id,branch_id,table_id) REFERENCES tables(tenant_id,branch_id,id));
CREATE UNIQUE INDEX one_open_session ON sessions(table_id) WHERE state='open' AND table_id IS NOT NULL;
CREATE TABLE customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,branch_id uuid NOT NULL,session_id uuid NOT NULL,token_hash text UNIQUE NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,branch_id,session_id) REFERENCES sessions(tenant_id,branch_id,id));
CREATE TABLE orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,branch_id uuid NOT NULL,session_id uuid NOT NULL,customer_id uuid,number bigint GENERATED ALWAYS AS IDENTITY,source text NOT NULL CHECK(source IN ('CUSTOMER_QR','STAFF_MANUAL')),type text NOT NULL CHECK(type IN ('DINE_IN','TAKEAWAY')),status text NOT NULL,created_by uuid,confirmed_by uuid,order_taker_user_id uuid,order_taker_name_snapshot text,order_taker_staff_id_snapshot text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,branch_id,id),FOREIGN KEY(tenant_id,branch_id,session_id) REFERENCES sessions(tenant_id,branch_id,id),FOREIGN KEY(tenant_id,customer_id) REFERENCES customers(tenant_id,id),FOREIGN KEY(tenant_id,created_by) REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,confirmed_by) REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,order_taker_user_id) REFERENCES users(tenant_id,id));
CREATE TABLE order_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,branch_id uuid NOT NULL,order_id uuid NOT NULL,product_id uuid NOT NULL,station_id uuid,status text NOT NULL,snapshot jsonb NOT NULL,amount bigint NOT NULL CHECK(amount>=0),UNIQUE(tenant_id,id),UNIQUE(tenant_id,branch_id,id),FOREIGN KEY(tenant_id,branch_id,order_id) REFERENCES orders(tenant_id,branch_id,id),FOREIGN KEY(tenant_id,product_id) REFERENCES resources(tenant_id,id),FOREIGN KEY(tenant_id,branch_id,station_id) REFERENCES resources(tenant_id,branch_id,id));
CREATE TABLE bills (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,branch_id uuid NOT NULL,session_id uuid NOT NULL,number bigint GENERATED ALWAYS AS IDENTITY,snapshot jsonb NOT NULL,total bigint NOT NULL CHECK(total>=0),status text NOT NULL DEFAULT 'finalized',generated_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,branch_id,id),FOREIGN KEY(tenant_id,branch_id,session_id) REFERENCES sessions(tenant_id,branch_id,id),FOREIGN KEY(tenant_id,generated_by) REFERENCES users(tenant_id,id));
CREATE TABLE bill_items (tenant_id uuid NOT NULL,branch_id uuid NOT NULL,bill_id uuid NOT NULL,item_id uuid NOT NULL UNIQUE,PRIMARY KEY(bill_id,item_id),FOREIGN KEY(tenant_id,branch_id,bill_id) REFERENCES bills(tenant_id,branch_id,id),FOREIGN KEY(tenant_id,branch_id,item_id) REFERENCES order_items(tenant_id,branch_id,id));
CREATE TABLE accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,branch_id uuid NOT NULL,name text NOT NULL,type text NOT NULL CHECK(type IN ('cash','bank','wallet','card','revenue','expense','payable','receivable','equity','clearing')),currency text NOT NULL,reference text,active boolean NOT NULL DEFAULT true,UNIQUE(tenant_id,id),UNIQUE(tenant_id,branch_id,id),FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id));
CREATE TABLE journals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,branch_id uuid NOT NULL,source text NOT NULL,source_id uuid NOT NULL,actor_id uuid NOT NULL,reverses uuid,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,branch_id,id),UNIQUE(tenant_id,source,source_id),FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id),FOREIGN KEY(tenant_id,actor_id) REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,reverses) REFERENCES journals(tenant_id,id));
CREATE TABLE journal_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,branch_id uuid NOT NULL,journal_id uuid NOT NULL,account_id uuid NOT NULL,amount bigint NOT NULL CHECK(amount<>0),FOREIGN KEY(tenant_id,branch_id,journal_id) REFERENCES journals(tenant_id,branch_id,id),FOREIGN KEY(tenant_id,account_id) REFERENCES accounts(tenant_id,id));
CREATE FUNCTION check_balance() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF (SELECT COALESCE(sum(amount),0) FROM journal_lines WHERE journal_id=NEW.journal_id)<>0 THEN RAISE EXCEPTION 'Unbalanced journal'; END IF; RETURN NULL; END $$;
CREATE CONSTRAINT TRIGGER journal_balanced AFTER INSERT ON journal_lines DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_balance();
CREATE FUNCTION immutable_posting() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Posted ledger records are immutable; use reversal'; END $$;
CREATE TRIGGER immutable_lines BEFORE UPDATE OR DELETE ON journal_lines FOR EACH ROW EXECUTE FUNCTION immutable_posting();
CREATE TRIGGER immutable_journals BEFORE UPDATE OR DELETE ON journals FOR EACH ROW EXECUTE FUNCTION immutable_posting();
CREATE TABLE shifts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,branch_id uuid NOT NULL,account_id uuid NOT NULL,user_id uuid NOT NULL,opening bigint NOT NULL CHECK(opening>=0),opened_at timestamptz NOT NULL DEFAULT now(),closed_at timestamptz,actual bigint,expected bigint,variance bigint,note text,reviewed_by uuid,UNIQUE(tenant_id,id),UNIQUE(tenant_id,branch_id,id),FOREIGN KEY(tenant_id,branch_id,account_id) REFERENCES accounts(tenant_id,branch_id,id),FOREIGN KEY(tenant_id,user_id) REFERENCES users(tenant_id,id));
CREATE UNIQUE INDEX one_drawer_shift ON shifts(account_id) WHERE closed_at IS NULL;
CREATE TABLE documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,branch_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN ('purchase','expense')),supplier_id uuid,invoice text,data jsonb NOT NULL,total bigint NOT NULL CHECK(total>0),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,branch_id,id),FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id),FOREIGN KEY(tenant_id,branch_id,supplier_id) REFERENCES resources(tenant_id,branch_id,id),FOREIGN KEY(tenant_id,created_by) REFERENCES users(tenant_id,id));
CREATE UNIQUE INDEX supplier_invoice ON documents(tenant_id,branch_id,supplier_id,lower(invoice)) WHERE invoice IS NOT NULL;
CREATE TABLE payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,branch_id uuid NOT NULL,bill_id uuid,document_id uuid,account_id uuid NOT NULL,shift_id uuid,amount bigint NOT NULL CHECK(amount>0),direction integer NOT NULL CHECK(direction IN (-1,1)),kind text NOT NULL,reference text,note text,tendered bigint,received_by uuid NOT NULL,verified_by uuid,verified_at timestamptz,status text NOT NULL CHECK(status IN ('pending','verified')),refund_of uuid,paid_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,branch_id,id),FOREIGN KEY(tenant_id,branch_id,bill_id) REFERENCES bills(tenant_id,branch_id,id),FOREIGN KEY(tenant_id,branch_id,document_id) REFERENCES documents(tenant_id,branch_id,id),FOREIGN KEY(tenant_id,branch_id,account_id) REFERENCES accounts(tenant_id,branch_id,id),FOREIGN KEY(tenant_id,branch_id,shift_id) REFERENCES shifts(tenant_id,branch_id,id),FOREIGN KEY(tenant_id,received_by) REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,verified_by) REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,branch_id,refund_of) REFERENCES payments(tenant_id,branch_id,id),CHECK((bill_id IS NULL)<>(document_id IS NULL)));
CREATE TABLE audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,branch_id uuid,actor_id uuid,action text NOT NULL,target_id uuid,data jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id),FOREIGN KEY(tenant_id,actor_id) REFERENCES users(tenant_id,id));
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON audit FOR EACH ROW EXECUTE FUNCTION immutable_posting();
CREATE TABLE events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,branch_id uuid NOT NULL,type text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id));
CREATE TABLE print_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,branch_id uuid NOT NULL,destination text NOT NULL,source_id uuid NOT NULL,payload jsonb NOT NULL,state text NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','dispatched','failed')),attempts integer NOT NULL DEFAULT 0,error text,created_by uuid,reprint_of uuid,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id),FOREIGN KEY(tenant_id,created_by) REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,reprint_of) REFERENCES print_jobs(tenant_id,id));
CREATE TABLE media (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,branch_id uuid,object_key text NOT NULL UNIQUE,thumb_key text,size bigint NOT NULL,public boolean NOT NULL DEFAULT false,mime text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id));
CREATE TABLE idempotency (tenant_id uuid NOT NULL,branch_id uuid NOT NULL,actor text NOT NULL,key text NOT NULL,hash text NOT NULL,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,actor,key),FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id));
CREATE FUNCTION tenant_scope() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('app.tenant',true),'')::uuid $$;
CREATE FUNCTION branch_scope() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('app.branch',true),'')::uuid $$;
CREATE FUNCTION auth_lookup(address text) RETURNS SETOF users LANGUAGE sql SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT * FROM users WHERE email=lower(address) AND active $$;
CREATE FUNCTION qr_lookup(hash text) RETURNS TABLE(tenant_id uuid,branch_id uuid,table_id uuid) LANGUAGE sql SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT tenant_id,branch_id,id FROM tables WHERE qr_hash=hash $$;
CREATE FUNCTION customer_lookup(hash text) RETURNS SETOF customers LANGUAGE sql SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT * FROM customers WHERE token_hash=hash AND created_at>now()-interval '12 hours' $$;
REVOKE ALL ON FUNCTION auth_lookup(text),qr_lookup(text),customer_lookup(text) FROM PUBLIC;
